<script lang="ts">import type { Snippet } from 'svelte'; import type { HTMLAttributes } from 'svelte/elements'; import { getToastProviderContext } from './toast-context.svelte.js'; export interface Props extends Omit<HTMLAttributes<HTMLOListElement>, 'children'> { children?: Snippet; ref?: HTMLOListElement | null; } let { children, ref = $bindable(null), onpointerenter, onpointerleave, onfocusin, onfocusout, ...rest }: Props = $props(); const provider = getToastProviderContext();</script><ol bind:this={ref} {...rest} aria-label="Notifications" onpointerenter={(event) => { onpointerenter?.(event as PointerEvent & { currentTarget: EventTarget & HTMLOListElement }); provider.hovering = true; provider.pause(); }} onpointerleave={(event) => { onpointerleave?.(event as PointerEvent & { currentTarget: EventTarget & HTMLOListElement }); provider.hovering = false; provider.resume(); }} onfocusin={(event) => { onfocusin?.(event as FocusEvent & { currentTarget: EventTarget & HTMLOListElement }); provider.focused = true; provider.pause(); }} onfocusout={(event) => { onfocusout?.(event as FocusEvent & { currentTarget: EventTarget & HTMLOListElement }); if (!ref?.contains(event.relatedTarget as Node)) { provider.focused = false; provider.resume(); } }}>{@render children?.()}</ol>
